-- Every web sign-in used to add another 'Web Dashboard' device. Keep one per user: the most
-- recently seen live one (the device web sign-in now reuses), else the most recent revoked one.
-- References from synced rows move to the kept device; extra devices are then deleted, unless a
-- card was generated by one (cards.device_id is its lane), in which case it is only revoked.
-- Browser sessions bound to a deleted device end; the next sign-in lands on the kept device.
CREATE TEMP TABLE web_device_dupes ON COMMIT DROP AS
WITH ranked AS (
  SELECT id, user_id,
         row_number() OVER (PARTITION BY user_id
                            ORDER BY revoked_at IS NOT NULL, last_seen_at DESC NULLS LAST, created_at DESC) AS rn
    FROM devices
   WHERE platform = 'web'
)
SELECT d.id AS dupe_id, k.id AS keep_id
  FROM ranked d JOIN ranked k ON k.user_id = d.user_id AND k.rn = 1
 WHERE d.rn > 1;

UPDATE cards c SET last_device_id = x.keep_id FROM web_device_dupes x WHERE c.last_device_id = x.dupe_id;
UPDATE card_projects t SET device_id = x.keep_id FROM web_device_dupes x WHERE t.device_id = x.dupe_id;
UPDATE observations t SET device_id = x.keep_id FROM web_device_dupes x WHERE t.device_id = x.dupe_id;
UPDATE standups t SET device_id = x.keep_id FROM web_device_dupes x WHERE t.device_id = x.dupe_id;
UPDATE day_goals t SET device_id = x.keep_id FROM web_device_dupes x WHERE t.device_id = x.dupe_id;
UPDATE user_docs t SET device_id = x.keep_id FROM web_device_dupes x WHERE t.device_id = x.dupe_id;

UPDATE devices d SET revoked_at = COALESCE(d.revoked_at, now())
  FROM web_device_dupes x
 WHERE d.id = x.dupe_id AND EXISTS (SELECT 1 FROM cards c WHERE c.device_id = x.dupe_id);

DELETE FROM devices d
 USING web_device_dupes x
 WHERE d.id = x.dupe_id AND NOT EXISTS (SELECT 1 FROM cards c WHERE c.device_id = x.dupe_id);
